import {
  absText,
  charFromDigit,
  compareAbsText,
  digitFromChar,
  isNegativeText,
  negateIntegerText,
  normalizeIntegerText,
  normalizeUnsignedText,
} from './normalize.mjs';

export function addUnsignedText(left, right) {
  const a = normalizeUnsignedText(left);
  const b = normalizeUnsignedText(right);
  const digits = [];
  let carry = 0;
  let aIndex = a.length - 1;
  let bIndex = b.length - 1;

  while (aIndex >= 0 || bIndex >= 0 || carry > 0) {
    let sum = carry;
    if (aIndex >= 0) {
      sum += digitFromChar(a[aIndex]);
      aIndex -= 1;
    }
    if (bIndex >= 0) {
      sum += digitFromChar(b[bIndex]);
      bIndex -= 1;
    }

    carry = sum >= 10 ? 1 : 0;
    digits.push(charFromDigit(sum - (carry * 10)));
  }

  return digits.reverse().join('');
}

export function subtractUnsignedText(left, right) {
  const a = normalizeUnsignedText(left);
  const b = normalizeUnsignedText(right);
  if (compareAbsText(a, b) < 0) {
    throw new Error(`cannot subtract ${b} from ${a}`);
  }

  const digits = [];
  let borrow = 0;
  let aIndex = a.length - 1;
  let bIndex = b.length - 1;

  while (aIndex >= 0) {
    let difference = digitFromChar(a[aIndex]) - borrow;
    if (bIndex >= 0) {
      difference -= digitFromChar(b[bIndex]);
      bIndex -= 1;
    }

    if (difference < 0) {
      difference += 10;
      borrow = 1;
    } else {
      borrow = 0;
    }

    digits.push(charFromDigit(difference));
    aIndex -= 1;
  }

  return normalizeUnsignedText(digits.reverse().join(''));
}

export function multiplyUnsignedByDigit(value, digit) {
  const normalized = normalizeUnsignedText(value);
  if (digit === 0 || normalized === '0') {
    return '0';
  }
  if (digit === 1) {
    return normalized;
  }

  const digits = [];
  let carry = 0;
  for (let index = normalized.length - 1; index >= 0; index -= 1) {
    const product = (digitFromChar(normalized[index]) * digit) + carry;
    const remainder = product % 10;
    carry = (product - remainder) / 10;
    digits.push(charFromDigit(remainder));
  }

  while (carry > 0) {
    const remainder = carry % 10;
    carry = (carry - remainder) / 10;
    digits.push(charFromDigit(remainder));
  }

  return digits.reverse().join('');
}

export function multiplyUnsignedText(left, right) {
  const a = normalizeUnsignedText(left);
  const b = normalizeUnsignedText(right);
  if (a === '0' || b === '0') {
    return '0';
  }

  let multiplicand = a;
  let multiplier = b;
  if (multiplicand.length < multiplier.length) {
    multiplicand = b;
    multiplier = a;
  }

  let result = '0';
  let zeroPadding = '';
  for (let index = multiplier.length - 1; index >= 0; index -= 1) {
    const digit = digitFromChar(multiplier[index]);
    if (digit !== 0) {
      const partial = `${multiplyUnsignedByDigit(multiplicand, digit)}${zeroPadding}`;
      result = addUnsignedText(result, partial);
    }
    zeroPadding += '0';
  }

  return result;
}

export function addIntegerText(left, right) {
  const a = normalizeIntegerText(left);
  const b = normalizeIntegerText(right);
  const aNegative = isNegativeText(a);
  const bNegative = isNegativeText(b);

  if (aNegative === bNegative) {
    const magnitude = addUnsignedText(absText(a), absText(b));
    if (magnitude === '0') {
      return '0';
    }
    return aNegative ? `-${magnitude}` : magnitude;
  }

  const comparison = compareAbsText(a, b);
  if (comparison === 0) {
    return '0';
  }

  const magnitude = comparison > 0
    ? subtractUnsignedText(absText(a), absText(b))
    : subtractUnsignedText(absText(b), absText(a));
  const negative = comparison > 0 ? aNegative : bNegative;
  return negative ? `-${magnitude}` : magnitude;
}

export function subtractIntegerText(left, right) {
  return addIntegerText(left, negateIntegerText(right));
}

export function multiplyIntegerText(left, right) {
  const a = normalizeIntegerText(left);
  const b = normalizeIntegerText(right);
  if (a === '0' || b === '0') {
    return '0';
  }

  const magnitude = multiplyUnsignedText(absText(a), absText(b));
  const negative = isNegativeText(a) !== isNegativeText(b);
  return negative ? `-${magnitude}` : magnitude;
}

