import { isIntegerLiteral } from '../integer/index.mjs';

const REQUIRED_ARGUMENTS = [
  { name: 'a', metavar: 'A' },
  { name: 'b', metavar: 'B' },
  { name: 'c', metavar: 'C' },
  { name: 'd', metavar: 'D' },
  { name: 'e', metavar: 'E' },
  { name: 'f', metavar: 'F' },
];

const REQUIRED_NAMES = new Set(REQUIRED_ARGUMENTS.map((argument) => argument.name));

export class CliExit extends Error {
  constructor(code, output, stream) {
    super(output);
    this.name = 'CliExit';
    this.code = code;
    this.output = output;
    this.stream = stream;
  }
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
  --e E
  --f F`;
}

function errorOutput(programName, message) {
  return `${formatUsage(programName)}
${programName}: error: ${message}`;
}

function splitLongOption(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { option: token, hasInlineValue: false, inlineValue: '' };
  }

  return {
    option: token.slice(0, equalsIndex),
    hasInlineValue: true,
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function isOptionLike(token) {
  return token.startsWith('-') && !isIntegerLiteral(token);
}

export function getProgramName(pathValue) {
  if (!pathValue) {
    return 'test20.mjs';
  }

  const parts = pathValue.split('/');
  return parts[parts.length - 1] || pathValue;
}

export function parseTest20Args(argv, programName) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, formatHelp(programName), 'stdout');
    }

    if (token.startsWith('-h=') || token.startsWith('--help=')) {
      const { inlineValue } = splitLongOption(token);
      throw new CliExit(
        2,
        errorOutput(
          programName,
          `argument -h/--help: ignored explicit argument '${inlineValue}'`,
        ),
        'stderr',
      );
    }

    if (token.startsWith('--')) {
      const { option, hasInlineValue, inlineValue } = splitLongOption(token);
      const argumentName = option.slice(2);

      if (!REQUIRED_NAMES.has(argumentName)) {
        extras.push(token);
        continue;
      }

      let valueToken = inlineValue;
      if (!hasInlineValue) {
        const nextToken = argv[index + 1];
        if (nextToken === undefined || isOptionLike(nextToken)) {
          throw new CliExit(
            2,
            errorOutput(programName, `argument --${argumentName}: expected one argument`),
            'stderr',
          );
        }
        valueToken = nextToken;
        index += 1;
      }

      if (!isIntegerLiteral(valueToken)) {
        throw new CliExit(
          2,
          errorOutput(
            programName,
            `argument --${argumentName}: invalid int value: '${valueToken}'`,
          ),
          'stderr',
        );
      }

      values[argumentName] = valueToken;
      continue;
    }

    extras.push(token);
  }

  const missing = REQUIRED_ARGUMENTS
    .filter((argument) => !(argument.name in values))
    .map((argument) => `--${argument.name}`);
  if (missing.length > 0) {
    throw new CliExit(
      2,
      errorOutput(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
      'stderr',
    );
  }

  if (extras.length > 0) {
    throw new CliExit(
      2,
      errorOutput(programName, `unrecognized arguments: ${extras.join(' ')}`),
      'stderr',
    );
  }

  return values;
}

