export class ZeroDivisionError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ZeroDivisionError';
  }
}

function reduceFraction(numerator, denominator) {
  let normalizedNumerator = normalizeIntegerText(numerator);
  let normalizedDenominator = normalizeIntegerText(denominator);

  if (isZeroText(normalizedDenominator)) {
    throw new ZeroDivisionError(
      `Fraction(${normalizedNumerator}, ${normalizedDenominator})`,
    );
  }

  if (normalizedDenominator[0] === '-') {
    normalizedNumerator = negateIntegerText(normalizedNumerator);
    normalizedDenominator = normalizedDenominator.slice(1);
  }

  const divisor = gcdText(normalizedNumerator, normalizedDenominator);
  return {
    numerator: exactDivideIntegerText(normalizedNumerator, divisor),
    denominator: exactDivideIntegerText(normalizedDenominator, divisor),
  };
}

export class Fraction {
  constructor(numerator, denominator = '1') {
    const reduced = reduceFraction(numerator, denominator);
    this.numerator = reduced.numerator;
    this.denominator = reduced.denominator;
    Object.freeze(this);
  }

  static fromInteger(value) {
    return new Fraction(value, '1');
  }

  add(other) {
    const numerator = addIntegerText(
      multiplyIntegerText(this.numerator, other.denominator),
      multiplyIntegerText(other.numerator, this.denominator),
    );
    const denominator = multiplyIntegerText(this.denominator, other.denominator);
    return new Fraction(numerator, denominator);
  }

  multiply(other) {
    return new Fraction(
      multiplyIntegerText(this.numerator, other.numerator),
      multiplyIntegerText(this.denominator, other.denominator),
    );
  }

  divide(other) {
    if (isZeroText(other.numerator)) {
      throw new ZeroDivisionError(`Fraction(${other.denominator}, ${other.numerator})`);
    }
    return new Fraction(
      multiplyIntegerText(this.numerator, other.denominator),
      multiplyIntegerText(this.denominator, other.numerator),
    );
  }

  reciprocal() {
    return new Fraction(this.denominator, this.numerator);
  }

  greaterThan(other) {
    const left = multiplyIntegerText(this.numerator, other.denominator);
    const right = multiplyIntegerText(other.numerator, this.denominator);
    return compareIntegerText(left, right) > 0;
  }

  toString() {
    return this.denominator === '1'
      ? this.numerator
      : `${this.numerator}/${this.denominator}`;
  }
}

